def _appointment_slice_from_combined_payload(
    payload: Dict[str, object],
) -> Optional[Dict[str, object]]:
    """从组合 directive 载荷抽出任免字段；无任免声明返 None。

    只保留任免成案所需键，剥离 grant 的 execution_surface / amount 等，
    避免 appointment 案卷撞「execution_surface 与案卷动作策略不符」。
    """
    action = str(payload.get("appoint_action") or "").strip()
    name = str(payload.get("name") or "").strip()
    if action not in {"任命", "罢免"} or not name:
        return None
    office = str(payload.get("office") or "").strip()
    if action == "任命" and not office:
        return None
    sliced: Dict[str, object] = {
        "name": name, "office": office, "appoint_action": action,
    }
    for key in (
        "appointment_tenure", "任别", "faction", "summon_after",
        "text", "affair_id", "region_id", "endorsements", "reason", "recommendation",
    ):
        value = payload.get(key)
        if value not in (None, ""):
            sliced[key] = value
    return sliced

def _is_gazette_public_event(item: dict) -> bool:
    """Turn-report gazette rows have their own directory carrier; exclude from 公开说法."""
    source_id = str(item.get("source_id") or "")
    return (
        source_id.startswith("projection:turn_report:")
        or (source_id.startswith("turn_report:") and source_id.endswith(":public"))
        or (source_id.startswith("turn_report:") and not source_id.endswith(":public"))
    )

def _count_failed_person_slots(
    result: Dict[str, Any], *, db: Any, content: Any,
) -> int:
    """首抽整个结果的人物失败槽数（顶层 roster + 全 drafts；机构/泛称排除）。"""
    n = 0
    if "participant_roster" in result:
        n += _count_failed_person_slots_in_roster(
            result.get("participant_roster"), db=db, content=content,
        )
    for draft in result.get("drafts") or []:
        if isinstance(draft, dict) and "participant_roster" in draft:
            n += _count_failed_person_slots_in_roster(
                draft.get("participant_roster"), db=db, content=content,
            )
    return n

def gate_cond_is_text(cond: str) -> bool:
    """cond 是否文本比较（==/!= 非数字 RHS，或 in=a|b）——与 runtime _gate_passed 文本分支同判。"""
    sm = re.match(r"^(==|!=|in=)\s*(.+)$", cond.strip())
    return bool(sm and (sm.group(1) == "in=" or not re.match(r"^-?\d+$", sm.group(2).strip())))

def displaced_talent_pool_results(displaced_parts: object) -> List[Dict[str, object]]:
    if not isinstance(displaced_parts, list):
        return []
    results: List[Dict[str, object]] = []
    for part in displaced_parts:
        name_part = str(part).split(":", 1)[0].strip()
        if not name_part:
            continue
        row = character_row(name_part)
        if row is None:
            continue
        if str(row["office"] or "") != "听用候铨" or str(row["reason_code"] or "") != "被顶替":
            continue
        results.append(
            {
                "name": name_part,
                "动作": "处置",
                "status": "active",
                "reason": "被顶替",
                "reason_code": "被顶替",
                "office": "听用候铨",
                "office_type": "身名分",
                "derived_from": "被顶替",
                # applier 合成级联回声：信用写端只消费 extractor 宣告本体行。
                "cascade_echo": True,
            }
        )
    return results

def covert_task_from_payload(payload: object) -> Optional[Dict[str, object]]:
    """#1376 候选 payload → typed contract 字段；不读 tags / title / content。"""
    if not isinstance(payload, Mapping):
        return None
    nested = payload.get("covert_task")
    source: Mapping[str, object]
    if isinstance(nested, Mapping):
        source = nested
    else:
        source = payload
    kind = str(source.get("kind") or payload.get("kind") or "").strip()
    axes = source.get("axes")
    if axes is None:
        axes = payload.get("axes")
    delivery = source.get("delivery") if isinstance(source.get("delivery"), Mapping) else source
    unit = str(
        delivery.get("unit")
        or source.get("delivery_unit")
        or payload.get("delivery_unit")
        or ""
    ).strip()
    target = delivery.get("target_units")
    if target is None:
        target = source.get("delivery_target_units")
    if target is None:
        target = payload.get("delivery_target_units")
    direction = source.get("direction")
    if direction is None:
        direction = payload.get("direction")
    effect_sign = delivery.get("effect_sign")
    if effect_sign is None:
        effect_sign = source.get("effect_sign")
    purpose = delivery.get("purpose")
    if purpose is None:
        purpose = source.get("purpose")
    category = delivery.get("category")
    if category is None:
        category = source.get("category")
    account = delivery.get("account")
    if account is None:
        account = source.get("account")
    target_kind = delivery.get("target_kind")
    if target_kind is None:
        target_kind = source.get("target_kind")
    if target_kind is None:
        target_kind = payload.get("target_kind")
    target_id = delivery.get("target_id")
    if target_id is None:
        target_id = source.get("target_id")
    if target_id is None:
        target_id = payload.get("target_id")
    region = delivery.get("region")
    if region is None:
        region = source.get("region")
    field = delivery.get("field")
    if field is None:
        field = source.get("field")
    region_target = delivery.get("target")
    if region_target is None:
        region_target = source.get("target")
    person_action = delivery.get("person_action")
    if person_action is None:
        person_action = source.get("person_action")
    investigation_target = str(
        delivery.get("investigation_target")
        or source.get("investigation_target")
        or payload.get("investigation_target")
        or ""
    ).strip()
    investigation_fact = str(
        delivery.get("investigation_fact")
        or source.get("investigation_fact")
        or payload.get("investigation_fact")
        or ""
    ).strip()
    if not kind and not unit and target is None and not normalize_axes(axes) and not investigation_target:
        return None
    out: Dict[str, object] = {}
    if kind:
        out["kind"] = kind

def _admit_transit_departure(
    item: Dict[str, object],
    row: Dict[str, object],
    valid_regions: set[str],
) -> tuple[Optional[Dict[str, object]], Optional[tuple[str, str]]]:
    """Return the canonical, write-free departure projection or its item rejection."""
    if "location" in item:
        return None, ("行止只接受 transit_to 启程", "invalid_transition")
    transit_to = str(item.get("transit_to") or "").strip()
    if not transit_to:
        return None, ("transit_to 缺失", "missing_field")
    if str(row.get("status") or "active") != "active":
        return None, ("行止 仅适用于 active 人物", "invalid_transition")
    if transit_to not in valid_regions:
        return None, ("transit_to 地区不存在", "missing_ref")
    try:
        tone = normalize_travel_tone(item.get("行程语气"))
    except ValueError:
        return None, ("行程语气不在闭合枚举", "invalid_enum")
    previous_destination = str(row.get("transit_to") or "")
    if previous_destination and previous_destination != transit_to:
        return None, ("在途人物不可改道", "invalid_transition")
    location = str(row.get("location") or "")
    if location not in valid_regions:
        return None, None
    matrix = DistanceMatrix.from_file(bundled_path("content", "distance_matrix.json"))
    distance = matrix.travel_time(location, transit_to)
    if not math.isfinite(distance) or distance < 0 or (location != transit_to and distance <= 0):
        raise ValueError(f"invalid baked travel time: {location!r} -> {transit_to!r}")
    terminal_location = transit_to if distance == 0 else location
    terminal_transit_to = "" if distance == 0 else transit_to
    return {
        "location": terminal_location,
        "transit_to": terminal_transit_to,
        "distance": distance,
        "tone": tone,
        "speed": None if distance == 0 else TRAVEL_SPEED_BY_TONE[tone],
        "material": (
            terminal_location != location
            or terminal_transit_to != previous_destination
        ),
    }, None

def pending_power_gate_value(key: str) -> Optional[int]:
    parts = key.split(".")
    if not parts or parts[0] != "power":
        return None
    agg = None
    if parts[-1] in _GATE_AGG_FUNCS:
        agg = parts[-1]
        parts = parts[:-1]
    if len(parts) != 3:
        return None
    _, id_segment, raw_field = parts
    field = _gate_sql_field("power", raw_field, key, kind="numeric")
    if field not in _PENDING_POWER_GATE_FIELDS:
        return None
    ids = [pid for pid in id_segment.split("|") if pid]
    if not ids or not any(field in pending_power_fields.get(pid, {}) for pid in ids):
        return None
    values: List[int] = []
    for pid in ids:
        row = power_row(pid)
        if row is None:
            return None
        values.append(int(row[field]))
    if len(values) == 1:
        return values[0]
    if agg is None:
        agg = "min"
    return int(_GATE_AGG_FUNCS[agg](values))

def apply_assembled_to_payload(
    payload: MutableMapping[str, object],
    assembled: Mapping[str, object],
) -> None:
    """把 assemble 结果写回 directive/rescript payload 核心字段。"""
    for key in _CORE_KEYS:
        if key not in assembled:
            payload.pop(key, None)
            continue
        val = assembled[key]
        if val in (None, ""):
            payload.pop(key, None)
        else:
            payload[key] = val

def strip_json_fence(text: str) -> str:
    match = re.search(r"```(?:json)?\s*(.*?)```", text, re.S)
    if match:
        return match.group(1).strip()
    return text.strip()

def decode_plea_meta(origin_context: object) -> Dict[str, object]:
    text = str(origin_context or "").strip()
    if not text.startswith(_META_PREFIX):
        return {}
    raw = text[len(_META_PREFIX):]
    try:
        data = json.loads(raw)
    except (TypeError, ValueError):
        return {}
    if not isinstance(data, dict):
        return {}
    return data

def confirm_dossier_links(
    minister_reply: str,
    dossier_candidates: Optional[List[Dict[str, Any]]],
    suggested_links: Any,
    llm_config: Any = None,
) -> List[Dict[str, Any]]:
    """Use one structured semantic verdict to narrow model-suggested links.

    Internal IDs are capabilities only: the verdict may select an ID only from
    both the reader-visible candidates and the producer's structured proposal.
    A failed/ambiguous verdict authorises nothing.
    """
    candidates = {
        int(row["id"]): str(row.get("secret_title") or row.get("decree_text") or "")
        for row in (dossier_candidates or [])
        if isinstance(row, dict) and type(row.get("id")) is int
    }
    proposals = _normalize_dossier_link_proposals(dossier_candidates, suggested_links)
    if not proposals:
        return []
    prompt = (
        "你是案卷关联确认判词，不是对话角色。只依据【大臣最终可见回话】的完整语义判断；"
        "否定、仅引用旧案、模糊复述、长短标题包含歧义、未明确承诺关联，均不得确认。"
        "内部ID只用于输出，不是确认依据。只输出合法JSON："
        "{\"confirmed_links\":[{\"target_dossier_id\":整数,\"relation_type\":\"护卫/稽核/接应\"}]}。\n"
        "【可选提议】\n" + "\n".join(
            f"- #{target} {candidates[target]}；{relation}；{item['note']}"
            for (target, relation), item in proposals.items()
        ) + "\n【大臣最终可见回话】\n" + (minister_reply or "（空）")
    )
    try:
        raw, _ = _run_json_extractor_for_config(prompt, llm_config, tag="dossier_link_confirmation")
        verdict = _loads_lenient(raw) or {}
    except Exception as exc:
        _log(f"案卷关联确认失败：{exc}")
        return []
    if not isinstance(verdict, dict):
        return []
    links = verdict.get("confirmed_links")
    if not isinstance(links, list):
        return []
    confirmed = set()
    for link in links:
        if not isinstance(link, dict) or type(link.get("target_dossier_id")) is not int:
            return []
        relation = link.get("relation_type")
        if relation not in DOSSIER_LINK_TYPES:
            return []
        confirmed.add((link["target_dossier_id"], relation))
    return [item for identity, item in proposals.items() if identity in confirmed]

def _optional_positive_dossier_id(raw: object, *, field: str) -> Optional[int]:
    """#658：typed dossier id 单权威——真正缺省→None；一旦出现只接正整数。

    拒 0/负/bool/float/数字字符串。target 与 backing 共吃，禁第二份 optional-positive。
    """
    if raw in (None, ""):
        return None
    value = strict_int(raw, accept_numeric_strings=False)
    if value <= 0:
        raise ValueError(f"{field} 非法 shape：{raw!r}")
    return value

def building_detail(self, name_or_id: str, qualitative: bool = False) -> str:
    key = (name_or_id or "").strip()
    row = self.conn.execute(
        "SELECT * FROM buildings WHERE id = ? OR name = ?", (key, key)
    ).fetchone()
    if row is None:
        row = self.conn.execute(
            "SELECT * FROM buildings WHERE name LIKE ?", (f"%{key}%",)
        ).fetchone()
    if row is None:
        raise ValueError(f"未找到建筑 '{name_or_id}'")
    metric = str(row["output_metric"])
    if metric in ("民心", "皇威") and qualitative:
        out = building_output_effect(metric, row["output_amount"])
    else:
        out = f"产出{metric}{row['output_amount']}/{TURN_UNIT}" if metric else "无结算产出"
    if qualitative:
        level, condition, risk = building_qualitative_fields(row)
        return (
            f"{row['name']}（{row['category']}，{row['region_id']}，{row['origin']}）："
            f"规模{level}，{condition}，维护{row['maintenance']}{MONEY_UNIT}/{TURN_UNIT}，风险{risk}，{out}。\n"
            f"{row['status']}"
        )
    return (
        f"{row['name']}（{row['category']}，{row['region_id']}，{row['origin']}）："
        f"等级{row['level']}，完好{row['condition']}，"
        f"维护{row['maintenance']}{MONEY_UNIT}/{TURN_UNIT}，风险{row['risk']}，{out}。\n"
        f"{row['status']}"
    )

def list_dossier_links(
