def _as_finite_nonnegative_float(label: str, value: object) -> float:
    if isinstance(value, bool):
        raise ValueError(f"{label} 非数值：{value!r}")
    if value in (None, ""):
        return 0.0
    try:
        amount = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{label} 非数值：{value!r}") from exc
    if not math.isfinite(amount) or amount < 0:
        raise ValueError(f"{label} 非法：{value!r}")
    return amount

def _commitment_remaining_from_gate(
    gate: Dict[str, str],
    state: GameState,
    db: GameDB,
) -> Optional[float]:
    remaining = 0.0
    found = False
    for key, cond in gate.items():
        cond_text = str(cond or "").strip()
        m = re.match(r"^(>=|<=|>|<|==)\s*(-?\d+)$", cond_text)
        if not m:
            continue
        val = _eval_gate_key(str(key), state.metrics, db)
        if val is None:
            continue
        try:
            val_num = float(val)
        except (TypeError, ValueError):
            continue
        op, target = m.group(1), int(m.group(2))
        if op == "<=":
            need = max(0.0, val_num - target)
        elif op == "<":
            need = 0.0 if val_num < target else float(int(val_num - target) + 1)
        elif op == ">=":
            need = max(0.0, target - val_num)
        elif op == ">":
            need = 0.0 if val_num > target else float(int(target - val_num) + 1)
        else:
            need = abs(val_num - target)
        remaining += need
        found = True
    return remaining if found else None

def _legacy_commitment_stop_gate(resolve_condition: object) -> Dict[str, str]:
    text = str(resolve_condition or "").strip()
    match = re.fullmatch(r"(character\.[^.]+\.loyalty)\s*((?:>=|>)\s*\d+)", text)
    if not match:
        return {}
    return {match.group(1): match.group(2).replace(" ", "")}

def classify_transport_failure(error: BaseException) -> ClassifiedFailure:
    """先分类后重试。只认 typed 信号；不从错误散文猜语义（ADR 0142）。

    可重试：瞬断/空转/5xx/408/429/空输出；召对 429 例外在调用策略落实。
    不可重试：其余确定性 4xx（#1452 Unknown model 等带 4xx status）。
    未知（无 status 的笼统 stream/run error）→ 不洗成瞬断，立即上浮。

    本函数是 APITimeout/Connection/Status/空输出/RunError → code/retryable/status 的唯一权威
    （llm_unavailable_from_error / run_error_event_failure / empty_output_failure 委派或同构）。
    """
    if isinstance(error, TransportIdleTimeout):
        return ClassifiedFailure(
            retryable=True,
            code="llm_idle_timeout",
            status_code=None,
            provider_message=str(error) or "idle timeout",
            message="LLM 调用空转超时。",
        )
    if isinstance(error, APITimeoutError):
        return ClassifiedFailure(
            retryable=True,
            code="llm_timeout",
            status_code=None,
            provider_message=str(error),
            message="LLM 调用超时。",
        )
    if isinstance(error, APIConnectionError):
        return ClassifiedFailure(
            retryable=True,
            code="llm_connection_error",
            status_code=None,
            provider_message=str(error),
            message="LLM 连接失败。",
        )
    if isinstance(error, APIStatusError):
        status_i = _coerce_status(getattr(error, "status_code", None))
        code = f"llm_http_{status_i}" if status_i is not None else "llm_http_error"
        return ClassifiedFailure(
            retryable=_status_retryable(status_i),
            code=code,
            status_code=status_i,
            provider_message=str(error),
            message=f"LLM 调用失败（HTTP {status_i}）。" if status_i else "LLM 调用失败。",
        )
    if isinstance(error, LLMUnavailable):
        status = error.status_code
        code = str(error.code or "llm_unavailable")
        pmsg = str(error.provider_message or error.message or "")
        status_i = _coerce_status(status)
        if status_i is not None:
            return ClassifiedFailure(
                retryable=_status_retryable(status_i),
                code=code,
                status_code=status_i,
                provider_message=pmsg,
                message=str(error.message or pmsg or "LLM 调用失败。"),
            )
        if code in {
            "llm_timeout",
            "llm_connection_error",
            "llm_idle_timeout",
            "llm_empty_output",
        }:
            return ClassifiedFailure(
                retryable=True,
                code=code,
                status_code=None,
                provider_message=pmsg,
                message=str(error.message or pmsg or "LLM 调用失败。"),
            )
        if code.startswith("llm_http_"):
            tail = code[len("llm_http_") :]
            status_from_code = _coerce_status(tail)
            if status_from_code is not None:
                return ClassifiedFailure(
                    retryable=_status_retryable(status_from_code),
                    code=code,
                    status_code=status_from_code,
                    provider_message=pmsg,
                    message=str(error.message or pmsg or "LLM 调用失败。"),

def _resolve_inside(root: Path, rel: str) -> Path:
    root_r = root.resolve()
    raw = str(rel or "").strip()
    if not raw or raw in {".", "./"}:
        return root_r
    if Path(raw).is_absolute() or raw.startswith("~"):
        raise ValueError("材料路径越出目录")
    candidate = (root_r / raw).resolve()
    try:
        candidate.relative_to(root_r)
    except ValueError as exc:
        raise ValueError("材料路径越出目录") from exc
    return candidate

def _building_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, list):
        return False
    numeric = set(BUILDING_SCORE_FIELDS + BUILDING_QUANTITY_FIELDS)
    text = set(BUILDING_TEXT_FIELDS)
    for op in raw:
        if not isinstance(op, dict):
            continue
        action = str(op.get("action") or "").strip().lower()
        if action == "create":
            category = str(op.get("category") or "").strip()
            if category in BUILDING_CATEGORIES and _nonempty_text(op.get("region_id")):
                return True
            continue
        if action == "remove":
            if _nonempty_text(op.get("building_id")):
                return True
            continue
        if action != "modify" or not _nonempty_text(op.get("building_id")):
            continue
        for raw_field, value in op.items():
            field = BUILDING_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
            if field in numeric and _nonzero_int(value):
                return True
            if field in text and _nonempty_text(value):
                return True
    return False

def building_output_effect(metric: str, amount: object, prefix: str = "") -> str:
    """Describe a building's output without exposing abstract score values."""
    if not metric:
        return ""
    if metric in ("民心", "皇威"):
        try:
            output = int(0 if amount is None else amount)
        except (TypeError, ValueError):
            output = 0
        effect = "略有裨益" if output < 10 else "颇有裨益" if output < 30 else "有显著裨益"
        return f"{prefix}对{metric}{effect}"
    return f"{prefix}产出{metric}{amount}"

