def settle_applied_arrived_summons(
    db: Any, applied: Dict[str, Any],
) -> List[str]:
    """结清已由 canonical applier 成功续启赴京的在途召旨。

    只认 applied_person_changes 中未拒收且 transit_to=beizhili 的成功行止；
    同人全部 kind=in_transit 未结 origin 一并结清。失败/空 applied 为 no-op。
    外层 settle atomic 使行止与结清同成同败（_should_commit 已为 False）。
    """
    accepted = {
        str(item.get("name") or item.get("人物") or "").strip()
        for item in (applied.get("applied_person_changes") or [])
        if isinstance(item, dict)
        and not item.get("rejected")
        and str(item.get("transit_to") or item.get("去向") or "").strip() == "beizhili"
    }
    accepted.discard("")
    if not accepted:
        return []
    settled: List[str] = []
    for item in list_unsettled_summons(db):
        # 月度判官只收 in_transit origin；成功续启后 transit_to 已变，
        # 后置投影不再是 arrived，故按 person∈accepted 结清。
        if item["kind"] != "in_transit" or item["person_name"] not in accepted:
            continue
        origin = str(item["origin_id"])
        if settle_summon_origin(db, origin):
            settled.append(origin)
    return settled

def plea_kind_set(meta: Dict[str, object]) -> Set[str]:
    """merged 条所载松手类 = primary ∪ absorbed（persist 链统一读口）。"""
    kinds: Set[str] = set()
    primary = str(meta.get("breach_kind") or "").strip()
    if primary:
        kinds.add(primary)
    absorbed = meta.get("absorbed_breach_kinds") or []
    if isinstance(absorbed, list):
        for raw in absorbed:
            kind = str(raw or "").strip()
            if kind:
                kinds.add(kind)
    return kinds

def _dedup_path(chunks: List[str]) -> str:
    """把若干 PATH 片段拼成一条去重保序的 search path。"""
    seen: set = set()
    dirs: List[str] = []
    for chunk in chunks:
        for d in chunk.split(os.pathsep):
            if d and d not in seen:
                seen.add(d)
                dirs.append(d)
    return os.pathsep.join(dirs)

def _normalize_dossier_link_proposals(
    dossier_candidates: Optional[List[Dict[str, Any]]],
    suggested_links: Any,
) -> Dict[Tuple[int, str], Dict[str, Any]]:
    """Return the one canonical, visible set of dossier-link proposals."""
    candidate_ids = {
        row["id"] for row in (dossier_candidates or [])
        if isinstance(row, dict) and type(row.get("id")) is int
    }
    proposals: Dict[Tuple[int, str], Dict[str, Any]] = {}
    for link in suggested_links if isinstance(suggested_links, list) else []:
        if not isinstance(link, dict) or type(link.get("target_dossier_id")) is not int:
            continue
        target = link["target_dossier_id"]
        relation = str(link.get("relation_type") or "").strip()
        note = str(link.get("note") or "")
        if target in candidate_ids and relation in DOSSIER_LINK_TYPES and note:
            proposals[(target, relation)] = {
                "target_dossier_id": target, "relation_type": relation, "note": note}
    return proposals

def _strip_comment(t: str, i: int, out: List[str], n: int) -> int:
    if t[i] == "/" and i + 1 < n and t[i + 1] == "/":
        nl = t.find("\n", i)
        return n if nl == -1 else nl  # 跳到行尾（换行本身保留，由下一轮 append）
    out.append(t[i])
    return i + 1

def _delivery_matches_economy(item: Mapping[str, object], delivery: Mapping[str, object]) -> bool:
    try:
        delta = float(item.get("delta") or 0)
    except (TypeError, ValueError):
        return False
    sign = int(delivery.get("effect_sign") or 0)
    if sign < 0 and delta >= 0:
        return False
    if sign > 0 and delta <= 0:
        return False
    if sign < 0:
        purpose = str(delivery.get("purpose") or "").strip()
        if str(item.get("purpose") or "").strip() != purpose:
            return False
        if purpose == "补饷":
            if str(item.get("target_kind") or "").strip() != str(delivery.get("target_kind") or "").strip():
                return False
            if str(item.get("target_id") or "").strip() != str(delivery.get("target_id") or "").strip():
                return False
    category = str(delivery.get("category") or "").strip()
    if str(item.get("category") or "").strip() != category:
        return False
    account = str(delivery.get("account") or "").strip()
    if str(item.get("account") or "").strip() != account:
        return False
    return True

def _sponsor_names(db: Any, dossier_id: int) -> List[str]:
    dossier = db.get_decree_dossier(int(dossier_id))
