def _migrate_character_location_aliases(self) -> None:
    """#654 G：幂等扫描 characters.location；精确别名→canonical；全字段回传 transit。"""
    rows = self.conn.execute(
        "SELECT name, location, transit_to, transit_distance_remaining, "
        "transit_speed_factor, transit_start_turn FROM characters"
    ).fetchall()
    if not rows:
        return
    from ming_sim.matching import canonical_region_id_exact

    regions = getattr(self.content, "regions", None) or {}
    changed = False
    for row in rows:
        raw = str(row["location"] or "")
        if not raw.strip():
            continue
        # 已是 canonical id → skip
        if raw in regions:
            continue
        hit = canonical_region_id_exact(raw, regions)
        if hit is None:
            raise ValueError(
                f"开档 location 未知别名：name={row['name']!r} location={raw!r}"
            )
        if hit == raw:
            continue
        self.set_character_transit(
            str(row["name"]),
            location=hit,
            transit_to=str(row["transit_to"] or ""),
            distance_remaining=row["transit_distance_remaining"],
            speed_factor=row["transit_speed_factor"],
            start_turn=int(row["transit_start_turn"] or 0),
            content=self.content,
            commit=False,
        )
        changed = True
    if changed:
        self.conn.commit()

def _seed_guilt_storage_value(value: object) -> str:
    """Serialize the content-layer guilt mapping into the existing DB TEXT column."""
    if isinstance(value, Mapping):
        if not value:
            return ""
        crime = str(value.get("crime") or "")
        severity = str(value.get("severity") or "无").strip()
        return safe_json_dumps({"crime": crime, "severity": severity}, ensure_ascii=False)
    return str(value or "")

def validate_fiscal_config_values(self, values: Dict[str, int]) -> None:
    if not values:
        return
    cfg = self.get_fiscal_config()
    overlay = dict(cfg)
    normalized: Dict[str, int] = {}
    for raw_key, raw_value in values.items():
        key = str(raw_key or "").strip()
        value = int(raw_value)
        minimum = self.fiscal_config_minimum_value(key)
        if minimum is not None and value < minimum:
            raise ValueError(f"fiscal_config.{key} 不得低于结构地板 {minimum}")
        pair = _CENTRAL_LOSS_RATE_PAIRS.get(key)
        if pair is not None and (value < 0 or value > 100):
            raise ValueError(f"fiscal_config.{key} 须在 0..100")
        normalized[key] = value
        overlay[key] = value

    checked_pairs = set()
    for key in normalized:
        pair = _CENTRAL_LOSS_RATE_PAIRS.get(key)
        if pair is None or pair in checked_pairs:
            continue
        checked_pairs.add(pair)
        human_key, sink_key = pair
        human = int(overlay.get(human_key, 0) or 0)
        sink = int(overlay.get(sink_key, 0) or 0)
        if human + sink > 100:
            raise ValueError(f"{human_key}+{sink_key} 不得超过 100%")

def _record_unknown_sections(
    collector: RejectionCollector, declaration: Mapping[str, object], turn: int,
    source: Provenance,
) -> None:
    """顶层键不在已知 section 之列（拼错字段名等）→ 逐个记一条
    ``invalid_shape`` 拒收，不静默漏项（ADR 0015 决定 7 / 票面 AC1，J2）。"""
    for key in declaration.keys():
        if key in _KNOWN_SECTIONS:
            continue
        collector.record(str(key), RejectedItem(
            item={"raw_value": declaration[key]}, reason=f"未知 section：{key}",
            category="invalid_shape", source=source,
        ), turn)

def _graph_edges(graph: Mapping[str, object]) -> dict[str, list[tuple[str, float]]]:
    raw_nodes = graph.get("nodes")
    raw_edges = graph.get("edges")
    if not isinstance(raw_nodes, Mapping) or not isinstance(raw_edges, list):
        raise ValueError("distance graph must contain nodes object and edges array")

    nodes = set(raw_nodes)
    adjacency = {node: [] for node in nodes}
    for index, raw_edge in enumerate(raw_edges):
        if not isinstance(raw_edge, Mapping):
            raise ValueError(f"edges[{index}] must be an object")
        start = raw_edge.get("from")
        end = raw_edge.get("to")
        if not isinstance(start, str) or not isinstance(end, str):
            raise ValueError(f"edges[{index}] endpoints must be strings")
        if start not in nodes or end not in nodes:
            raise ValueError(f"edges[{index}] references an unknown node")
        cost = _number(raw_edge.get("cost"), f"edges[{index}].cost")
        adjacency[start].append((end, cost))
        adjacency[end].append((start, cost))
    return adjacency

def stage(
    self, *, decree_ref: str, declaration: Mapping[str, object], turn: int,
    visible_refs: Mapping[str, object] | None = None,
    verdict: Mapping[str, object] | None = None,
    questions: list | None = None,
    forecast_text: str | None = None,
) -> int:
    ref = str(decree_ref or "").strip()
    if not ref:
        raise ValueError("decree_ref 不能为空")
    if not isinstance(declaration, Mapping):
        raise ValueError("声明须为对象")
    def write() -> int:
        if self._is_closed(ref):
            raise DecreeAlreadySettled(
                f"decree_ref 已作废或已结算，不能再暂存新声明：{ref}（如需再起该旨，请用新的 decree_ref）"
            )
        cur = self._conn.execute(
            "INSERT INTO staged_declarations "
            "(decree_ref, declaration_json, visible_refs_json, status, created_turn, "
            "verdict_json, questions_json, forecast_text) "
            "VALUES (?, ?, ?, 'staged', ?, ?, ?, ?)",
            (
                ref,
                sanitize_sqlite_text(json.dumps(declaration, ensure_ascii=False)),
                json.dumps(visible_refs or {}, ensure_ascii=False),
                int(turn),
                None if verdict is None else sanitize_sqlite_text(
                    json.dumps(dict(verdict), ensure_ascii=False),
                ),
                None if questions is None else sanitize_sqlite_text(
                    json.dumps(list(questions), ensure_ascii=False),
                ),
                None if forecast_text is None else sanitize_sqlite_text(forecast_text),
            ),
        )
        return int(cur.lastrowid)
    if connection_owns_transaction(self._conn):
        with atomic(SimpleNamespace(conn=self._conn)):
            return write()
    return write()

def normalize_locality_scope(raw: object) -> str:
    """{'全国'/'单省'/'无'/缺省 → national/single/none}；枚举外 fail-loud。"""
    if raw is None:
        return "none"
    text = str(raw).strip()
    if not text:
        return "none"
    if text in _SCOPE_ALIASES:
        scope = _SCOPE_ALIASES[text]
    else:
        scope = text
    if scope not in LOCALITY_SCOPES:
        raise ValueError(f"locality_scope 非法：{raw!r}")
    return scope

def _oracle_order(p: Dict[str, Any], key: str, default: tuple) -> tuple:
    """oracle 侧序参重算：独立于落账的 _resolve_order_param。"""
    raw = p.get(key)
    if raw is None:
        return tuple(default)
    if isinstance(raw, str) or not isinstance(raw, (list, tuple)):
        raise ValueError(f"param {key} 非 list/tuple")
    if any(not isinstance(item, str) for item in raw):
        raise ValueError(f"param {key} 须为 {default} 的完整无重复排列：{raw!r}")
    items = tuple(raw)
    if len(items) != len(default) or set(items) != set(default) or len(set(items)) != len(items):
        raise ValueError(f"param {key} 须为 {default} 的完整无重复排列：{raw!r}")
    return items

def _appointment_region_id(payload: Dict[str, object]) -> str:
