def _api_runtime_slot(data: Dict[str, object]) -> Dict[str, object]:
    out: Dict[str, object] = {}
    for k in _API_RUNTIME_FIELDS:
        if k in _API_NUMERIC_FIELDS:
            caster, default = _API_NUMERIC_FIELDS[k]
            out[k] = _slot_number(data.get(k), caster, default)
        elif k == "advanced_thinking_level":
            out[k] = ""
        elif k == "reasoning_strength":
            out[k] = normalize_reasoning_strength(data.get(k))
        elif k == "default_headers":
            out[k] = _slot_header_table(data.get(k))
        else:
            out[k] = _slot_text(data, k)
    return out

def run_error_event_failure(
    content: object = None, status_code: object = None,
) -> ClassifiedFailure:
    """RunErrorEvent → 分类唯一构造。无 typed status 时不洗成瞬断（#1452）。"""
    pmsg = str(content or "").strip() or "stream error"
    status_i = _coerce_status(status_code)
    if status_i is None:
        return ClassifiedFailure(
            retryable=False,
            code="llm_stream_error",
            status_code=None,
            provider_message=pmsg,
            message=f"LLM 流式调用失败：{pmsg}",
        )
    return ClassifiedFailure(
        retryable=_status_retryable(status_i),
        code=f"llm_http_{status_i}",
        status_code=status_i,
        provider_message=pmsg,
        message=f"LLM 流式调用失败：{pmsg}",
    )

def _open_rescript_items(
    db: Any, state: Any, chain: Dict[str, Any],
) -> Dict[str, Any]:
    """本回合待答：打回三选 + 旨意请旨 + 世界段请旨。上月已答项不入。"""
    from ming_sim.decree_forecast import decree_ref_for_dossier

    turn = int(state.turn)
    triad = _this_turn_rescript_dossiers(db, turn)
    decree_questions: List[tuple[str, list]] = []
    seen_refs: set[str] = set()
    for dossier in db.list_decree_dossiers():
        ref = decree_ref_for_dossier(db, dossier)
        if ref in seen_refs:
            continue
        seen_refs.add(ref)
        questions = db.staged_declarations.questions_for(ref)
        if questions:
            # 未答请旨不论案卷创建回合，均须本回合收口（#1847 / 留中回流同审）。
            decree_questions.append((ref, questions))
    world_questions = [
        q for q in (chain.get("world_questions") or []) if isinstance(q, dict)
    ]
    return {
        "triad": triad,
        "decree_questions": decree_questions,
        "world_questions": world_questions,
    }

def parse_override_key(key: str) -> ParsedOverrideKey:
    """按 r3 白名单解析 override 键；非法形状 raise PayOrderKeyError（=ValueError）。

    词法：``<family><subject>[@<region_id>][#<source>]``。@ 必须先于 #；
    空词位（悬空 @ / #）、未知 family/subject、priority 族带 #、非军饷带 # 一律非法。
    本函数纯词法，不查 regions 表（region 存在性由物化端校验，防 @SX 类幻影 region）。
    """
    raw = str(key or "")
    body = raw
    source = ""
    if "#" in body:
        body, _, source = body.partition("#")
        if source not in _HAIRCUT_SOURCES:
            raise PayOrderKeyError(f"override 键 {raw!r}：#饷源后缀仅限 province/central")
    region = ""
    if "@" in body:
        body, _, region = body.partition("@")
        if not region:
            raise PayOrderKeyError(f"override 键 {raw!r}：@后 region_id 为空")
    if "@" in region or "#" in region:
        raise PayOrderKeyError(f"override 键 {raw!r}：scope 后缀顺序须为 @region#source")
    for family in (HAIRCUT_FAMILY, *_PRIORITY_FAMILIES):
        if body.startswith(family):
            subject = body[len(family):]
            break
    else:
        raise PayOrderKeyError(f"override 键 {raw!r}：未知键族（须 due_priority_*/arrears_priority_*/due_haircut_bp_*）")
    if family == HAIRCUT_FAMILY:
        if subject not in DUE_SUBJECTS:
            raise PayOrderKeyError(f"override 键 {raw!r}：未知折发科目 {subject!r}")
        if source and subject != "军饷":
            raise PayOrderKeyError(f"override 键 {raw!r}：饷源后缀仅军饷科目合法")
    else:
        legal = DUE_SUBJECTS if family == DUE_PRIORITY_FAMILY else ARREARS_SUBJECTS
        if subject not in legal:
            raise PayOrderKeyError(f"override 键 {raw!r}：{family}*/ 未知科目 {subject!r}")
        if source:
            # r3：序无饷源维度，# 后缀非法
            raise PayOrderKeyError(f"override 键 {raw!r}：priority 键族不允许 #饷源后缀")
    return ParsedOverrideKey(family=family, subject=subject, region=region, source=source)

def metric_delta(before: Dict[str, int], after: Dict[str, int]) -> Dict[str, int]:
    keys = list(before.keys())
    for key in after:
        if key not in before:
            keys.append(key)
    return {key: after.get(key, 0) - before.get(key, 0) for key in keys if after.get(key, 0) != before.get(key, 0)}

def apply_appointment(
    db: GameDB,
    state: GameState,
    content: GameContent,
    data: Optional[Dict[str, object]] = None,
    llm_config: Optional[LLMConfig] = None,
    commit: bool = True,
) -> Tuple[str, str]:
    """诏书任命共用落地：建档入库，本回合即可召见。"""
    if not data:
        return ("", "")
    if "approved" in data and not bool(data.get("approved")):
        return ("", "")
    name = str(data.get("name") or "").strip()
    office = str(data.get("office") or "").strip()
    if not name or not office:
        return ("", "")
    office = normalize_office(office)
    # 显式名分（office_type ∈ PERSON_TITLE_KINDS）在此建 Character 前就得保住：add_character 的
    # 名分守卫看的是 character.office_type，若这里先被 infer 反推成官职（office='诸生'→'生员'），
    # 守卫永远见不到名分、误建 offices/character_offices（#1059 codex l6h）。
    office_type = resolve_office_type_preserving_title(
        office,
        str(data.get("office_type") or "").strip(),
        "待铨",
        llm_config or db.llm_config,
    )
    if office_type == "后宫":
        return ("", "")

    # ── 查重：精确名 + aliases 命中即拒，不重复建档 ──────────
    # 身份归一认识未仕/宗藩——在册者（含史可法诸生）由此拒新建，走 apply_office_appointment。
    if name in content.characters:
        return ("", "")
    existing = _find_existing_minister(content, name, db)
    if existing is not None:
        return ("", "")

    # ── 职位替换：腾缺现任者 → dismissed ───────────────────────────
    displaced = ""
    replaces = str(data.get("replaces") or "").strip()
    if replaces and replaces in content.characters:
        old = content.characters[replaces]
        if old.status == "active":
            db.set_character_status(
                state, replaces, "dismissed",
                reason=f"{office}改授{name}，原任去职",
                content=content,
                commit=commit,
            )
            displaced = replaces

    person_fields = canonical_new_appointment_person_fields(
        content, data.get("faction"),
    )
    character = Character(
        name=name,
        office=office,
        office_type=office_type,
        aliases=[],
        personal_skills=[],
        power_id="ming",
        status="active",
        office_region=str(
            data.get("office_region") or data.get("region_id") or ""
        ).strip(),
        **person_fields,
    )
    content.characters[name] = character
    db.add_character(state, character, llm_config=llm_config, commit=commit)
    # add_character 已写入并分配 portrait_id，回写到内存对象
    row = db.conn.execute(
        "SELECT portrait_id FROM characters WHERE name=?", (name,)
    ).fetchone()
    if row:
        character.portrait_id = str(row["portrait_id"])
    return (name, displaced)

def expand_combo_failed_fields(fields: object) -> tuple[str, ...]:
    """把不变式 failed_fields 扩成可 merge 的 STRUCTURED_DECREE_FIELD_KEYS 子集。"""
    out: list[str] = []
    seen: set[str] = set()
    for raw in fields or ():  # type: ignore[union-attr]
        key = str(raw or "").strip()
        if not key:
            continue
        for item in _FAILED_FIELD_EXPAND.get(key, (key,)):
            if item in STRUCTURED_DECREE_FIELD_KEYS and item not in seen:
                seen.add(item)
                out.append(item)
    return tuple(out)

def _surface_capture(label: str, text: str) -> dict:
    """真报证据面：只记录非空与原文，不作 P4 措辞扫描判定（ADR 0143）。"""
    blob = str(text or "")
    return {
        "label": label,
        "non_empty": bool(blob.strip()),
        "text": blob,
    }

